<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router'
import { useSessionStore } from '@/stores/session'
import { useProduction } from '@/composables/useProduction'
import { useDelivery } from '@/composables/useDelivery'
import { useOperations } from '@/composables/useOperations'
import { ApiError, asApiError } from '@/api/client'
import { listMembers } from '@/api/modules/account'
import type { Member } from '@/api/types'
import { canDisplay } from '@/config/actions'
import { getTrade, money, triggers, yuanInput, type TradeRecord } from '@/api/modules/trade'
import { getProduction, productionContent, stages, type ProductionRecord } from '@/api/modules/production'
import { caseKinds, fulfillmentStates, getDeliveryStory, deliveryCaseEvidence, isCastMember, type CastMember, type DeliveryStory, type DeliveryWrite, type DeliveryCase } from '@/api/modules/customizationDelivery'
import { listSupply, validSupplyId, type SupplyRecord, type MediaType, type SupplyAsset } from '@/api/modules/supply'
import WorkspaceNav from '@/components/WorkspaceNav.vue'
import ApiErrorAlert from '@/components/ApiErrorAlert.vue'
import SupplyUpload from '@/components/SupplyUpload.vue'
import '@/styles/supply.css'
import '@/styles/trade.css'
import '@/styles/production.css'
import '@/styles/delivery.css'
const session=useSessionStore(),route=useRoute(),router=useRouter()
const creating=computed(()=>route.name==='delivery-new'),reviewer=computed(()=>route.name==='delivery-review'),projectId=computed(()=>String(route.params.recordId||'')),orderId=computed(()=>String(route.params.orderId||''))
const context=()=>({token:session.token,accountId:session.account?.id||'',partyId:reviewer.value?null:session.selectedId,revision:session.revision,scope:route.fullPath})
const ui=useProduction(context),flow=useDelivery(context),ops=useOperations(context)
const now=ref(Date.now())
const scripts=ref<SupplyRecord[]>([]),members=ref<Member[]>([])
const order=ref<TradeRecord|null>(null),project=ref<ProductionRecord|null>(null),story=ref<DeliveryStory|null>(null),menuOpen=ref(false),initializing=ref(true),pageLoading=ref(false),confirmation=ref(false),conflicted=ref(false),viewed=ref(false),previewUrl=ref(''),previewText=ref(''),previewVersion=ref(''),receiptConfirmed=ref(false),caseAssets=ref<string[]>([]),evidenceAssets=ref<string[]>([]),caseId=ref(''),caseKind=ref(''),caseReason=ref(''),resolution=reactive({decision:'',retained:'',order:'',reason:''}),reissueReason=ref('')
const form=reactive({line:'',script:'',license:'',assignee:'',purpose:'',territory:'',evidence:'',people:false}),cast=ref<CastMember[]>([])
const f=computed(()=>flow.value.value),p=computed(()=>project.value?.kind==='PROJECT'?project.value:null),o=computed(()=>order.value?.kind==='ORDER'?order.value:null)
const owner=computed(()=>!!session.selected&&session.selected.membership.current_status==='ACTIVE'&&session.selected.membership.roles.includes('OWNER')&&!['CLOSED','SUSPENDED'].includes(session.selected.party.current_status))
const buyer=computed(()=>owner.value&&p.value?.data.buyer_party_id===session.selectedId),merchant=computed(()=>owner.value&&p.value?.data.merchant_party_id===session.selectedId),assignee=computed(()=>p.value?.data.producer_party_id===session.selectedId&&p.value.data.assignee_account_id===session.account?.id)
const independent=computed(()=>reviewer.value&&!!p.value&&p.value.created_by!==session.account?.id&&!session.parties.some(a=>a.membership.current_status==='ACTIVE'&&[p.value?.data.buyer_party_id,p.value?.data.merchant_party_id,p.value?.data.producer_party_id].includes(a.party.id)))
const locked=computed(()=>ui.busy.value||flow.busy.value||ops.busy.value||now.value<Math.max(ui.retryAt.value,flow.retryAt.value,ops.retryAt.value)||!!ui.pending.value||!!flow.pending.value||!!ops.pending.value||conflicted.value&&!confirmation.value)
const lines=computed(()=>o.value?.data.quote.customization&&!o.value.data.quote.customization_change?o.value.data.quote.lines.filter(l=>l.line_kind==='PRODUCTION'&&l.specification.customization_delivery&&l.product_profile?.type==='PRIVATE_CUSTOMIZATION'):[])
const line=computed(()=>lines.value.find(l=>l.line_id===form.line)),roster=computed(()=>form.people?cast.value:[])
const createValid=computed(()=>owner.value&&o.value?.merchant_party_id===session.selectedId&&['OPEN','PARTIALLY_PAID','PAID','REWARD_FUNDED'].includes(o.value.current_status)&&line.value?.provider_party_id===session.selectedId&&[form.script,form.assignee,form.evidence].every(validSupplyId)&&(!form.license||validSupplyId(form.license))&&!!form.license===!!o.value.data.quote.license_reservation_id&&form.purpose.trim()&&form.territory.trim()&&(!form.people||cast.value.length>0&&cast.value.every(isCastMember)&&new Set(cast.value.map(c=>c.avatar_id)).size===cast.value.length))
const activeCase=computed(()=>f.value?.cases.find(c=>c.id===caseId.value&&c.current_status==='OPEN')),hasOpenCase=computed(()=>f.value?.cases.some(c=>c.current_status==='OPEN'))
const caseValid=computed(()=>(buyer.value||merchant.value)&&!hasOpenCase.value&&f.value&&!['CANCELLED','REFUND_REQUIRED','REFUNDED'].includes(f.value.state)&&Object.hasOwn(caseKinds,caseKind.value)&&caseReason.value.trim())
const resolutionValid=computed(()=>independent.value&&activeCase.value&&resolution.reason.trim()&&(resolution.decision==='RESUME'&&activeCase.value.data.kind!=='CREATIVE_CHANGE'||resolution.decision==='CANCEL'&&yuanInput(resolution.retained,0)!==null||resolution.decision==='CHANGE_ORDER'&&activeCase.value.data.kind==='CREATIVE_CHANGE'&&validSupplyId(resolution.order)))
const event=computed(()=>ops.notifications.value.find(n=>n.id===f.value?.receipt?.notification_event_id))
const canReceipt=computed(()=>buyer.value&&viewed.value&&previewVersion.value===f.value?.receipt?.version_id&&f.value?.receipt?.view_observed_at&&f.value.receipt.buyer_account_id===session.account?.id&&event.value?.read&&receiptConfirmed.value&&!f.value.receipt.started_at)
let disposed=false,ticket=0,timer=0
function resetPrivate(){ticket++;scripts.value=[];members.value=[];order.value=project.value=story.value=null;previewUrl.value=previewText.value=previewVersion.value='';viewed.value=receiptConfirmed.value=false;caseAssets.value=evidenceAssets.value=[];caseKind.value=caseReason.value=caseId.value=reissueReason.value='';Object.assign(resolution,{decision:'',retained:'',order:'',reason:''});Object.assign(form,{line:'',script:'',license:'',assignee:'',purpose:'',territory:'',evidence:'',people:false});cast.value=[];conflicted.value=confirmation.value=false;ui.revoke()}
watch(ui.securityRevision,resetPrivate,{flush:'sync'})
watch(flow.securityRevision,()=>{if(project.value){ui.clear();ops.clear()}},{flush:'sync'})
let clearing=false
watch([ui.error,flow.error,ops.error],errors=>{if(clearing)return;const e=errors.find(e=>e&&([401,403,404].includes(e.status)||['ARTIST_CONSENT_REQUIRED','ARTIST_HOSTING_REQUIRED','CUSTOMIZATION_CAST_SOURCE_CHANGED','PERSONAL_DATA_RESTRICTED','CUSTOMIZATION_CHANGE_PAYMENT_REVERSED'].includes(e.code)));if(!e)return;clearing=true;ui.clear();flow.clear();ops.clear();ui.error.value=e;clearing=false},{flush:'sync'})
watch([flow.conflictRevision,ui.conflictRevision],()=>{conflicted.value=true;confirmation.value=false;receiptConfirmed.value=false;if(validSupplyId(projectId.value))void ui.read('project',(i,s)=>getProduction(i,projectId.value,'PROJECT',s),r=>project.value=r)},{flush:'sync'})
watch(()=>f.value?.receipt?.delivery_id,(id,previous)=>{if(previous&&id!==previous){viewed.value=false;receiptConfirmed.value=false;previewVersion.value=previewUrl.value=previewText.value='';ui.revoke();ops.notifications.value=[]}})
watch(()=>[route.fullPath,session.selectedId,session.revision],()=>{menuOpen.value=false;if(!initializing.value)void load()})
async function load(){const t=++ticket,current=()=>!disposed&&t===ticket;pageLoading.value=true;try{if(creating.value){if(!validSupplyId(orderId.value))return;const r=await ui.read('order',(i,s)=>getTrade(i,orderId.value,'ORDER',s));if(current()&&r)order.value=r;return}if(!validSupplyId(projectId.value))return;const r=await ui.read('project',(i,s)=>getProduction(i,projectId.value,'PROJECT',s));if(!current()||!r)return;project.value=r;const d=await flow.load(r.id);if(!current()||!d)return;await ui.read('order',(i,s)=>getTrade(i,r.order_id,'ORDER',s),r=>order.value=r);if(current()&&buyer.value&&d.receipt)await ops.loadEvent(d.receipt.notification_event_id)}finally{if(current())pageLoading.value=false}}
onMounted(async()=>{const captured=session.capture();try{await Promise.all([session.loadAccount(),session.loadParties()]);if(!disposed&&session.current(captured)){initializing.value=false;await load()}}catch(e){if(!disposed&&session.current(captured))ui.error.value=asApiError(e)}finally{initializing.value=false}})
function leave(){if(!ui.pending.value&&!flow.pending.value&&!ops.pending.value)return true;ui.notice.value='原请求结果待核对，请先在本页恢复原操作。';return false}
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave)
function unload(e:BeforeUnloadEvent){if(!leave()){e.preventDefault();e.returnValue=''}}
onMounted(()=>{window.addEventListener('beforeunload',unload);timer=window.setInterval(()=>now.value=Date.now(),1000)});onUnmounted(()=>{disposed=true;ticket++;window.clearInterval(timer);window.removeEventListener('beforeunload',unload)})
async function readScripts(){if(locked.value)return;await ui.read('scripts',async(i,s)=>{const items:SupplyRecord[]=[],seen=new Set<string>();let cursor:string|null=null;do{const page=await listSupply(i,'WORK_VERSION',cursor,s);items.push(...page.items);cursor=page.next_cursor;if(cursor&&seen.has(cursor))throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'剧本目录分页未更新。'});if(cursor)seen.add(cursor)}while(cursor);return items.filter(r=>r.current_status==='REVIEWS_COMPLETE')},r=>scripts.value=r)}
async function readMembers(){if(locked.value||!canDisplay(session.selected?.party.allowed_actions,'MANAGE_MEMBERS'))return;await ui.read('members',async i=>{const items:Member[]=[],seen=new Set<string>();let cursor:string|null=null;do{const page=await listMembers(i.token,i.partyId!,cursor);items.push(...page.data.items);cursor=page.data.next_cursor;if(cursor&&seen.has(cursor))throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'当前成员目录分页未更新。'});if(cursor)seen.add(cursor)}while(cursor);return items.filter(m=>m.current_status==='ACTIVE')},r=>members.value=r)}
function addActor(){cast.value.push({person_id:'',avatar_id:'',supply_consent_id:'',artist_consent_ids:[],look_version_id:'',voice_version_id:null,usage:'EXISTING_MATERIAL'})}
function setRights(c:CastMember,e:Event){c.artist_consent_ids=(e.target as HTMLInputElement).value.trim().split(/[\s,，]+/).filter(Boolean)}
async function upload(file:File,type:MediaType,target:'project'|'case'){if(locked.value||!owner.value)return;await ui.write({path:'/supply/assets',resultKind:'ASSET',label:'上传私有依据',supply:{path:`/supply/assets?${new URLSearchParams({purpose:'RIGHTS_EVIDENCE',media_type:type})}`,blob:file,purpose:'RIGHTS_EVIDENCE',mediaType:type,kind:'ASSET',label:'上传私有依据'}},r=>{const id=(r as SupplyAsset).id;if(target==='project'){form.evidence=id;evidenceAssets.value=[id]}else caseAssets.value=[...caseAssets.value,id]})}
async function create(){if(locked.value||!createValid.value||!o.value)return;await ui.write({path:'/production/projects',resultKind:'PROJECT',label:'建立原订单定制项目',body:{order_id:o.value.id,line_id:form.line,script_version_id:form.script,license_project_id:form.license||null,assignee_account_id:form.assignee,purpose:form.purpose.trim(),territory:form.territory.trim(),consent_ids:[...new Set(roster.value.map(c=>c.supply_consent_id))],evidence_asset_id:form.evidence,fulfillment:{uses_identifiable_people:form.people,cast:roster.value}}},r=>void router.push(`/production/projects/${r.id}/fulfillment`))}
async function write(action:DeliveryWrite['action'],body:unknown,label:string){if(locked.value||!f.value)return;await flow.write({projectId:f.value.project_id,version:f.value.object_version,action,body,label});if(!flow.pending.value&&!flow.error.value){confirmation.value=false;conflicted.value=false;receiptConfirmed.value=false;await ui.read('project',(i,s)=>getProduction(i,projectId.value,'PROJECT',s),r=>project.value=r)}}
async function openCase(){if(caseValid.value)await write('cases',{kind:caseKind.value,reason:caseReason.value.trim(),evidence_asset_ids:caseAssets.value},'提交原项目问题工单')}
async function resolve(){if(!resolutionValid.value||!activeCase.value)return;await write('case-resolution',{case_id:activeCase.value.id,decision:resolution.decision,retained_minor:resolution.decision==='CANCEL'?yuanInput(resolution.retained,0):null,change_order_id:resolution.decision==='CHANGE_ORDER'?resolution.order:null,reason:resolution.reason.trim()},'保存独立处理决定')}
async function readStory(){if(locked.value||!f.value)return;const source=f.value.source;story.value=null;await ui.read('story',async(i,s)=>{const r=await getDeliveryStory(i,projectId.value,s);if(r.request_id!==source.request_id||r.submission_id!==source.submission_id||r.content_sha256!==source.content_sha256)throw new ApiError({status:503,code:'PRIVATE_CONTENT_MISMATCH',message:'故事与原成交提交不一致，已停止显示。'});return r},r=>story.value=r)}
async function readPreview(){if(locked.value||!f.value?.receipt||!buyer.value)return;const id=f.value.receipt.version_id;viewed.value=receiptConfirmed.value=false;previewUrl.value=previewText.value=previewVersion.value='';ui.revoke();await ui.read('receipt-preview',async(i,s)=>{const v=await getProduction(i,id,'VERSION',s);if(v.kind!=='VERSION')throw new Error('version');const file=await getProduction(i,v.data.preview_file_id,'FILE',s);if(file.kind!=='FILE')throw new Error('file');const bytes=await productionContent(i,id,'preview',s),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await bytes.arrayBuffer())),n=>n.toString(16).padStart(2,'0')).join('');if(bytes.size!==file.data.byte_size||hash!==file.data.content_sha256)throw new ApiError({status:503,code:'PRIVATE_CONTENT_MISMATCH',message:'预览内容校验未通过。'});if(!['text/plain','video/mp4'].includes(file.data.media_type))throw new ApiError({status:200,code:'UNSUPPORTED_CONTENT_TYPE',message:'本版文件暂不能在本页实际查看，请提交文件问题。'});return {id,blob:new Blob([bytes],{type:file.data.media_type}),text:file.data.media_type==='text/plain'?await bytes.text():null}},r=>{previewVersion.value=r.id;if(r.text!==null){previewText.value=r.text;viewed.value=true}else previewUrl.value=ui.objectUrl(r.blob)});if(!ui.error.value)await flow.load(projectId.value)}
function previewFailed(){viewed.value=false;receiptConfirmed.value=false;ui.notice.value='预览无法播放，尚未完成查看。请重读或提交文件问题。'}
async function readNotification(){if(locked.value||!viewed.value||previewVersion.value!==f.value?.receipt?.version_id||!event.value||event.value.read)return;const n=event.value;await ops.write({path:`/operations/notifications/${n.id}/read`,body:{},resultKind:'READ',resultId:n.id,recovery:'NOTIFICATIONS',label:'确认本次交付通知已读'},()=>void flow.load(projectId.value))}
async function readCaseEvidence(c:DeliveryCase,id:string){if(locked.value)return;await ui.read('case-evidence',(i,s)=>deliveryCaseEvidence(i,projectId.value,c.id,id,s),b=>{const u=ui.objectUrl(b),a=document.createElement('a');a.href=u;a.download=`问题依据-${id}`;a.click()})}
const workTitle=computed(()=>o.value?.data.quote.lines.find(l=>l.line_id===p.value?.data.line_id)?.title||'制作项目')
const date=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false})
const title=computed(()=>creating.value?'建立定制制作项目':reviewer.value?'定制工单独立处理':'制作与交付')
</script>
<template>
<div class="supply-workspace trade-workspace production-workspace editorial-workspace delivery-workspace" data-gallery="WEB-R04-DELIVERY"><header class="supply-header"><RouterLink to="/workspace" class="supply-brand">晶晶日上</RouterLink><span>故事成片 · 制作与交付</span><div class="account-actions"><span>{{session.account?.display_name||'当前账号'}}</span><button @click="session.logout().then(()=>router.push('/login'))">退出</button></div></header><div class="supply-layout"><aside class="supply-sidebar"><button class="outline editorial-menu-toggle" aria-controls="delivery-menu" :aria-expanded="menuOpen" @click="menuOpen=!menuOpen">工作区导航 <span>{{menuOpen?'收起':'展开'}}</span></button><div id="delivery-menu" class="editorial-menu" :class="{expanded:menuOpen}"><WorkspaceNav/><div class="supply-identity"><p v-if="reviewer">当前账号 · 独立处理岗位</p><template v-else><label for="delivery-party">当前办理身份</label><select id="delivery-party" :value="session.selectedId" :disabled="locked" @change="session.selectParty(($event.target as HTMLSelectElement).value)"><option v-for="a in session.parties" :key="a.party.id" :value="a.party.id">{{a.party.display_name}}</option></select></template></div></div></aside><main class="supply-main">
<div class="supply-heading"><div><p class="eyebrow">PRODUCTION JOURNAL / 04</p><h1>{{title}}</h1><p>{{creating?'从原成交约定出发，明确本次制作、负责人与出演授权。':'逐版完成制作、查看和确认，让每一步都有真实记录。'}}</p></div><button class="outline" :disabled="locked||pageLoading" @click="load">刷新原记录</button></div>
<ApiErrorAlert :error="ui.error.value"/><ApiErrorAlert :error="flow.error.value"/><ApiErrorAlert :error="ops.error.value"/><p v-if="ui.notice.value||flow.notice.value||ops.notice.value" class="supply-notice" role="status">{{ui.notice.value||flow.notice.value||ops.notice.value}}</p>
<section v-if="ui.pending.value||flow.pending.value||ops.pending.value" class="supply-warning"><h2>原请求结果待核对</h2><p>保留了原内容、原版本和请求编号。先读取原记录，再恢复同一次请求。</p><template v-if="flow.pending.value"><button :disabled="flow.busy.value" @click="flow.check">核对原项目</button><button :disabled="flow.busy.value||!flow.pending.value.checked" @click="flow.retry">恢复原履约请求</button></template><template v-if="ui.pending.value"><button :disabled="ui.busy.value" @click="ui.checkPending">核对原记录</button><button :disabled="ui.busy.value||!ui.pending.value.checked" @click="ui.retry">恢复原请求</button></template><template v-if="ops.pending.value"><button :disabled="ops.busy.value" @click="ops.checkPending">核对原通知</button><button :disabled="ops.busy.value||!ops.pending.value.checked" @click="ops.retry">恢复原通知请求</button></template></section>
<label v-if="conflicted" class="supply-warning trade-check"><input v-model="confirmation" type="checkbox">已核对刷新后的原记录，按保留的输入重新确认本次操作。</label>
<p v-if="initializing||pageLoading" class="supply-empty">正在读取当前获准内容……</p>
<template v-else-if="creating">
<section v-if="o" class="supply-card"><p class="eyebrow">01 / ORIGINAL AGREEMENT</p><h2>原成交订单</h2><dl class="supply-facts"><div><dt>订单编号</dt><dd class="identifier">{{o.id}}</dd></div><div><dt>原成交金额</dt><dd class="trade-amount">{{money(o.data.quote.total_minor)}}</dd></div><div><dt>实际收款 / 已退款</dt><dd>{{money(o.data.financial.received_minor)}} / {{money(o.data.financial.refunded_minor)}}</dd></div></dl><RouterLink :to="`/trade/orders/${o.id}`" class="button-link outline">核对原合同与付款节点</RouterLink></section>
<p v-if="!lines.length" class="supply-warning">本单没有可由本入口建立的私人定制明细。历史缺失履约条款的订单须先核对原约定；人工样片须走已绑定并由本人确认出演材料的专用委托流程。</p>
<form v-else @submit.prevent="create"><fieldset :disabled="locked||!owner"><section class="supply-card"><p class="eyebrow">02 / PRODUCTION BRIEF</p><h2>本次制作</h2><div class="trade-fields two"><label>原制作明细 *<select v-model="form.line" data-testid="delivery-line" required><option value="">请选择</option><option v-for="l in lines" :key="l.line_id" :value="l.line_id">{{l.title}} · {{l.line_id}}</option></select></label><label>已审剧本版本编号 *<input v-model="form.script" list="delivery-scripts" data-testid="delivery-script" required><datalist id="delivery-scripts"><option v-for="r in scripts" :key="r.id" :value="r.id">{{r.kind==='WORK_VERSION'?r.data.version.content.title:''}}</option></datalist></label><label>实际受派账号编号 *<select v-if="members.length" v-model="form.assignee" data-testid="delivery-assignee" required><option value="">选择当前机构受派账号</option><option v-for="m in members" :key="m.account_id" :value="m.account_id">{{m.account_id}} · {{m.role_code}}</option></select><input v-else v-model="form.assignee" data-testid="delivery-assignee" required placeholder="当前制作机构受派成员的完整账号编号"></label><label>关联许可项目编号<input v-model="form.license" :required="!!o?.data.quote.license_reservation_id" placeholder="原订单关联许可时填写"></label><label>本次用途 *<input v-model="form.purpose" maxlength="100" required></label><label>实际使用地域 *<input v-model="form.territory" maxlength="100" required></label></div><div class="supply-actions"><button type="button" class="outline" :disabled="locked" @click="readScripts">读取本方可用已审剧本</button><button v-if="canDisplay(session.selected?.party.allowed_actions,'MANAGE_MEMBERS')" type="button" class="outline" :disabled="locked" @click="readMembers">读取当前机构成员</button></div><p class="muted">须引用真实已审剧本和当前制作方成员；服务器核对原订单、权利与当前归属。</p><SupplyUpload label="身份、签署及权利依据" :ids="evidenceAssets" single :disabled="locked" @upload="(file,type)=>upload(file,type,'project')" @remove="evidenceAssets=[];form.evidence=''"/><label>已上传依据编号 *<input v-model="form.evidence" required></label></section>
<section class="supply-card"><p class="eyebrow">03 / CAST & RIGHTS</p><h2>出演者与授权</h2><label class="trade-check"><input v-model="form.people" type="checkbox" data-testid="delivery-has-cast">本项目使用可识别的真人或数字人</label><p class="muted">可以委托不含可识别人物的影片。使用他人出演形象时，逐位明确真人、数字人、形象及声音版本和本次授权。</p><template v-if="form.people"><div v-for="(c,n) in cast" :key="n" class="delivery-cast"><h3>出演者 {{n+1}}</h3><div class="trade-fields two"><label>真人档案编号 *<input v-model="c.person_id" required></label><label>数字人编号 *<input v-model="c.avatar_id" required></label><label>供给同意记录编号 *<input v-model="c.supply_consent_id" required></label><label>本次艺人授权编号 *<input :value="c.artist_consent_ids.join(', ')" required @input="setRights(c,$event)" placeholder="1—2份，用逗号分隔"></label><label>形象版本编号 *<input v-model="c.look_version_id" required></label><label>声音版本编号<input :value="c.voice_version_id||''" @input="c.voice_version_id=($event.target as HTMLInputElement).value||null" placeholder="授权涉及声音时必填"></label><label>实际制作方式 *<select v-model="c.usage"><option value="EXISTING_MATERIAL">使用已有材料</option><option value="NEW_GENERATION">需要新的生成制作</option></select></label></div><button type="button" class="outline" @click="cast.splice(n,1)">移除此出演者</button></div><button type="button" class="outline" :disabled="cast.length>=20" @click="addActor">添加出演者</button><p class="muted">新生成另需有效托管；可用授权、用途和地域由服务器逐项核验。</p></template></section><div class="trade-footer"><RouterLink :to="`/trade/orders/${orderId}`" class="button-link outline">返回原订单</RouterLink><button class="primary" data-testid="delivery-create" :disabled="locked||!createValid">提交项目独立核验</button></div></fieldset></form>
</template>
<template v-else-if="p&&f">
<section class="supply-card delivery-overview"><div><p class="eyebrow">01 / CURRENT PROGRESS</p><h2 data-testid="delivery-work-title">{{workTitle}}</h2><p class="supply-badge">{{fulfillmentStates[f.state]}}</p><p class="identifier">{{p.id}}</p></div><dl class="supply-facts"><div><dt>受派账号</dt><dd class="identifier">{{p.data.assignee_account_id}}</dd></div><div><dt>开工记录</dt><dd>{{f.started_at?date(f.started_at):'尚未开工'}}</dd></div><div><dt>创意修改 / 追加次数</dt><dd>{{f.creative_changes}} / {{f.additional_creative_changes}}</dd></div></dl><div class="supply-actions"><RouterLink :to="`/production/${reviewer?'reviews/projects':'projects'}/${p.id}`" class="button-link outline">{{reviewer?'项目核验与原材料':'项目、文件与正式版本'}}</RouterLink><RouterLink :to="`/trade/orders/${p.order_id}`" class="button-link outline">原订单与合同</RouterLink><button v-if="!reviewer&&assignee&&f.state==='PLANNED'" class="primary" :disabled="locked||!['READY','IN_PROGRESS'].includes(p.current_status)" data-testid="delivery-start" @click="write('start',{},'确认受派开工')">确认受派开工</button></div><p v-if="f.state==='PLANNED'" class="muted">实际负责账号在首期真实收款、独立核验和权利通过后确认开工。页面不代替签署或到账记录。</p></section>
<section class="supply-card"><h2>逐阶段制作记录</h2><ol class="delivery-stages"><li v-for="(name,key) in stages" :key="key"><span>{{name}}</span><strong>{{p.data.current[key]&&p.data.current[key]===p.data.accepted[key]?'本版已确认':p.data.current[key]?'已提交版本':'待制作'}}</strong><RouterLink v-if="p.data.current[key]" :to="`/production/${reviewer?'reviews/versions':'versions'}/${p.data.current[key]}`">查看本版</RouterLink></li></ol></section>
<section class="supply-card"><p class="eyebrow">02 / AGREED DELIVERY</p><h2>原约定与付款进度</h2><dl class="supply-facts"><div><dt>交付规则版本 / 来源</dt><dd>{{f.terms.version}} · {{f.terms.source_ref}}</dd></div><div><dt>预览与中款顺序</dt><dd>{{f.terms.preview_payment_order==='PREVIEW_BEFORE_INTERIM'?'先看正式预览，再确认中间条件':'按原合同先核对中款条件，再开放预览'}}</dd></div><div><dt>明确收讫后的确认期限</dt><dd>{{f.terms.acceptance_hours}} 小时</dd></div></dl><p class="long-text">{{f.terms.cancellation_terms}}</p><template v-if="o"><div class="table-wrap"><table><thead><tr><th>原付款节点</th><th>触发条件</th><th>约定金额</th></tr></thead><tbody><tr v-for="i in o.data.quote.installments" :key="i.key"><td>{{i.key}}</td><td>{{triggers[i.trigger]}}</td><td>{{money(i.allocations.reduce((s,a)=>s+a.amount_minor,0))}}</td></tr></tbody></table></div><p class="delivery-money">实际收款 {{money(o.data.financial.received_minor)}} <span>已退款 {{money(o.data.financial.refunded_minor)}}</span></p><RouterLink v-if="!reviewer" :to="`/trade/payments/new?orderId=${p.order_id}`" class="button-link outline">按原订单办理付款</RouterLink></template><p class="muted">付款金额和触发条件采用原订单；确认成片与付清款项后，服务器才允许正式文件下载。</p></section>
<section class="supply-card"><p class="eyebrow">03 / STORY & CAST</p><h2>原故事与出演归属</h2><dl class="supply-facts"><div><dt>原正式提交</dt><dd class="identifier">{{f.source.submission_id}}</dd></div><div><dt>原内容校验值</dt><dd class="identifier">{{f.source.content_sha256}}</dd></div></dl><button class="outline" :disabled="locked" @click="readStory">读取原成交故事</button><div v-if="story" class="delivery-story"><h3>{{story.template_snapshot.title}}</h3><dl><template v-for="field in story.template_snapshot.fields" :key="field.key"><dt>{{field.label}}</dt><dd>{{story.answers[field.key]||'未提供'}}</dd></template></dl></div><p v-if="!f.uses_identifiable_people" class="muted">原项目明确不使用可识别人物。</p><div v-for="(c,n) in f.cast" :key="c.avatar_id" class="delivery-cast"><h3>出演者 {{n+1}} · {{c.usage==='NEW_GENERATION'?'新的生成制作':'已有材料'}}</h3><dl class="supply-facts"><div><dt>真人 / 数字人</dt><dd class="identifier">{{c.person_id}} / {{c.avatar_id}}</dd></div><div><dt>形象 / 声音版本</dt><dd class="identifier">{{c.look_version_id}} / {{c.voice_version_id||'无声音版本'}}</dd></div><div><dt>供给同意 / 艺人授权</dt><dd class="identifier">{{c.supply_consent_id}} / {{c.artist_consent_ids.join('、')}}</dd></div></dl></div></section>
<section v-if="f.receipt" class="supply-card"><p class="eyebrow">04 / VIEW & ACKNOWLEDGE</p><h2>本次正式预览与收讫</h2><p class="identifier">本版 {{f.receipt.version_id}}</p><div class="supply-actions"><RouterLink :to="`/production/${reviewer?'reviews/versions':'versions'}/${f.receipt.version_id}`" class="button-link outline">逐项审片、反馈与验收</RouterLink><button v-if="buyer&&!reviewer" class="primary" :disabled="locked" data-testid="delivery-preview" @click="readPreview">读取本次受控预览</button></div><pre v-if="previewText" class="production-text-preview">{{previewText}}</pre><video v-if="previewUrl" :src="previewUrl" controls preload="metadata" class="production-video" aria-label="本次正式私有预览" @loadeddata="viewed=true" @error="previewFailed"/><template v-if="buyer&&!reviewer"><p v-if="viewed" class="muted">本版内容已能实际查看。请核对后确认通知和收讫。</p><div class="supply-actions"><button class="outline" :disabled="locked||!viewed||!event||event.read" data-testid="delivery-notification-read" @click="readNotification">{{event?.read?'本次交付通知已读':'确认本次交付通知已读'}}</button><button v-if="!event" class="outline" :disabled="locked" @click="ops.loadEvent(f.receipt!.notification_event_id)">读取本次交付通知</button></div><label class="trade-check"><input v-model="receiptConfirmed" type="checkbox" :disabled="locked||!viewed||!event?.read||!!f.receipt.started_at">我已实际查看本版并收到本次交付，明确确认收讫。</label><button class="primary" data-testid="delivery-receipt" :disabled="locked||!canReceipt" @click="write('delivery-receipt',{},'明确确认本次收讫')">确认本次收讫</button></template><dl class="supply-facts"><div><dt>实际收讫时间</dt><dd>{{f.receipt.started_at?date(f.receipt.started_at):'尚未明确确认'}}</dd></div><div><dt>服务器确认截止时间</dt><dd>{{f.receipt.deadline_at?date(f.receipt.deadline_at):'尚未起算'}}</dd></div></dl><p class="muted">打开页面和收到通知均不自动确认收讫。文件无法实际查看时，可在下方提交文件问题。</p><form v-if="!reviewer&&assignee&&f.state==='STARTED'" @submit.prevent="reissueReason.trim()&&write('reissue',{version_id:f!.receipt!.version_id,reason:reissueReason.trim()},'重新发出本版正式交付')"><label>重新交付理由<textarea v-model="reissueReason" :disabled="locked" maxlength="2000" required/></label><button class="outline" :disabled="locked||!reissueReason.trim()">重新发出本版交付通知</button></form></section>
<section class="supply-card"><p class="eyebrow">05 / CASES & AFTERCARE</p><h2>问题处理与取消核对</h2><p v-if="!f.cases.length" class="muted">原项目暂无问题工单。</p><article v-for="c in f.cases" :key="c.id" class="delivery-case"><h3>{{caseKinds[c.data.kind]}} <span class="supply-badge">{{c.current_status==='OPEN'?'待独立处理':'已保存处理决定'}}</span></h3><p class="identifier">{{c.id}} · {{date(c.data.opened_at)}}</p><p class="long-text">{{c.data.reason}}</p><div v-if="reviewer||c.data.opened_by_party_id===session.selectedId" class="supply-actions"><button v-for="id in c.data.evidence_asset_ids" :key="id" class="outline" :disabled="locked" @click="readCaseEvidence(c,id)">读取本工单依据 {{id.slice(0,8)}}</button></div><template v-if="c.data.resolution"><p>{{c.data.resolution.decision==='CANCEL'?'批准取消':c.data.resolution.decision==='CHANGE_ORDER'?'关联已付变更订单':'恢复原约定'}} · {{c.data.resolution.reason}}</p><RouterLink v-if="c.change_order_id" :to="`/trade/orders/${c.change_order_id}`" class="button-link outline">原工单的独立变更订单</RouterLink></template><RouterLink v-if="!reviewer&&merchant&&c.current_status==='OPEN'&&c.data.kind==='CREATIVE_CHANGE'" :to="`/trade/quotes/new?customizationProject=${p.id}&caseId=${c.id}`" class="button-link outline" data-testid="delivery-change-quote">从原工单建立独立变更报价</RouterLink></article>
<form v-if="!reviewer&&(buyer||merchant)" @submit.prevent="openCase"><fieldset :disabled="locked||!!hasOpenCase||['CANCELLED','REFUND_REQUIRED','REFUNDED'].includes(f.state)"><h3>提交原项目问题</h3><div class="trade-fields two"><label>问题类型 *<select v-model="caseKind" required><option value="">请选择</option><option v-for="(label,k) in caseKinds" :key="k" :value="k">{{label}}</option></select></label><label>具体问题与诉求 *<textarea v-model="caseReason" maxlength="4000" required/></label></div><SupplyUpload label="本工单私有依据" :ids="caseAssets" :disabled="locked||!!hasOpenCase" @upload="(file,type)=>upload(file,type,'case')" @remove="id=>caseAssets=caseAssets.filter(a=>a!==id)"/><p class="muted">提交后暂停原项目。原约定错误与新增创作要求分别处理；追加报价须关联本工单，原合同保持原记录。</p><button class="primary" :disabled="locked||!caseValid" data-testid="delivery-open-case">提交问题并暂停制作</button></fieldset></form>
<form v-if="reviewer" class="trade-review-form" @submit.prevent="resolve"><fieldset :disabled="locked||!independent"><h3>独立处理原工单</h3><div class="trade-fields two"><label>开放工单 *<select v-model="caseId" required><option value="">请选择</option><option v-for="c in f.cases.filter(c=>c.current_status==='OPEN')" :key="c.id" :value="c.id">{{caseKinds[c.data.kind]}} · {{c.id}}</option></select></label><label>处理决定 *<select v-model="resolution.decision" required><option value="">请选择</option><option value="RESUME" :disabled="activeCase?.data.kind==='CREATIVE_CHANGE'">按原约定恢复</option><option value="CANCEL">批准取消并明确应退金额</option><option value="CHANGE_ORDER" :disabled="activeCase?.data.kind!=='CREATIVE_CHANGE'">关联本工单已付变更订单</option></select></label><label v-if="resolution.decision==='CANCEL'">明确保留金额（元） *<input v-model="resolution.retained" inputmode="decimal" required placeholder="全退明确填写0"></label><label v-if="resolution.decision==='CHANGE_ORDER'">已付变更订单编号 *<input v-model="resolution.order" required></label><label>实际核对依据与决定理由 *<textarea v-model="resolution.reason" maxlength="4000" required/></label></div><p class="muted">未开工、制作失败、权利不可用或侵权应全退。其他保留金额不得超过实际收款及已确认阶段金额；批准不等于渠道退款。</p><button class="primary" :disabled="locked||!resolutionValid" data-testid="delivery-resolve">保存独立处理决定</button></fieldset></form>
<div v-if="f.cancellation" class="delivery-cancellation"><h3>取消金额与实际退款</h3><dl class="supply-facts"><div><dt>原核实收款</dt><dd>{{money(f.cancellation.received_minor)}}</dd></div><div><dt>批准保留 / 应退</dt><dd>{{money(f.cancellation.retained_minor)}} / {{money(f.cancellation.refund_minor)}}</dd></div><div><dt>已核实实际退款</dt><dd>{{money(f.cancellation.actual_refunded_minor)}}</dd></div></dl><div class="supply-actions"><button v-if="!reviewer" class="outline" :disabled="locked" @click="write('refund-sync',{},'核对原项目实际退款')">核对真实退款记录</button><RouterLink v-if="!reviewer" to="/trade/refunds/new" class="button-link outline">办理原付款退款</RouterLink></div></div></section>
<div class="trade-footer"><RouterLink :to="reviewer?'/production/reviews/projects':'/production/projects'" class="button-link outline">返回制作记录</RouterLink><RouterLink v-if="!reviewer" :to="`/operations/objects/PRODUCTION/${p.id}/comments`" class="button-link outline">原项目留言</RouterLink></div>
</template><p v-else class="supply-empty">当前没有可读取的履约记录，请核对原项目和办理权限。</p>
</main></div></div>
</template>
